function timeoutBilan(ish, limit, callback) {
    let tugadi = false;
    const taymer = setTimeout(() => {
        if (tugadi) return;
        tugadi = true;
        callback(new Error("Vaqt tugadi"));
    }, limit);

    ish((err, natija) => {
        if (tugadi) return;
        tugadi = true;
        clearTimeout(taymer);
        callback(err, natija);
    });
}

