const tinglovchilar = {};

function on(hodisa, callback) {
    (tinglovchilar[hodisa] ??= []).push(callback);
}

function emit(hodisa, ...args) {
    for (const callback of tinglovchilar[hodisa] ?? []) {
        callback(...args);
