const pechdagilar = new Map();

function buyurtmaBer(raqam, taom, vaqt) {
    const id = setTimeout(() => {
        pechdagilar.delete(raqam);
        console.log(`#${raqam} ${taom} tayyor`);
    }, vaqt);
    pechdagilar.set(raqam, id);
}

function bekorQil(raqam) {
    if (!pechdagilar.has(raqam)) return;
    clearTimeout(pechdagilar.get(raqam));
    pechdagilar.delete(raqam);
    console.log(`#${raqam} bekor qilindi`);
}

