function bolishCb(a, b, callback) {
    setTimeout(() => {
        if (b === 0) callback(new Error("Nolga bo'lib bo'lmaydi"));
        else callback(null, a / b);
    }, 20);
}

function bolish(a, b) {
    return new Promise((resolve, reject) => {
        bolishCb(a, b, (err, natija) => {
            if (err) reject(err);
            else resolve(natija);
        });
    });
}

