    yukla(tur)
        .catch((xato) => {
            if (xato instanceof TarmoqXatosi) return "keshdan o'qildi";
            throw xato;
        })
        .then((natija) => console.log(tur, "->", natija))
        .catch((xato) => console.log(tur, "-> yuqoriga uzatildi:", xato.name));
}

