function myAll(promises) {
    return new Promise((resolve, reject) => {
        const natijalar = [];
        let qoldi = promises.length;
        if (qoldi === 0) resolve(natijalar);
        promises.forEach((p, i) => {
            Promise.resolve(p).then((v) => {
                natijalar[i] = v;                       // tugash tartibi emas, indeks
                if (--qoldi === 0) resolve(natijalar);
