async function* countdown(from) {
    for (let i = from; i >= 1; i--) {
        await delay(20);       // kutamiz
        yield i;               // qiymatni tashqariga beramiz va to'xtaymiz
    }
    return "tamom";            // done: true bilan keladi, for await ko'rmaydi
}

for await (const step of countdown(3)) {
    console.log(step);         // 3, 2, 1
}

class Playlist {
    #songs;
    constructor(songs) {
        this.#songs = songs;
    }

    async *[Symbol.asyncIterator]() {
        for (const song of this.#songs) {
            await delay(10);
            yield song;
        }
    }
}

for await (const song of new Playlist(["Yulduz", "Oy"])) console.log(song);

async function* readConnection() {
    console.log("ulanish ochildi");
