async function* map(source, fn) {
    for await (const x of source) yield fn(x);
}

async function* filter(source, predicate) {
    for await (const x of source) if (predicate(x)) yield x;
}

async function* take(source, count) {
    let taken = 0;
    for await (const x of source) {
        yield x;
        if (++taken >= count) return;
    }
}

const squares = map(naturals(), (n) => n * n);
const odd = filter(squares, (n) => n % 2 === 1);
console.log(await Array.fromAsync(take(odd, 4)));

