async function* withItemTimeout(source, ms) {
    const iterator = source[Symbol.asyncIterator]();
    try {
        while (true) {
            let timer;
            const timeout = new Promise((_, reject) => {
                timer = setTimeout(() => reject(new Error(`element ${ms} ms ichida kelmadi`)), ms);
            });
            const result = await Promise.race([iterator.next(), timeout]).finally(() => clearTimeout(timer));
            if (result.done) return;
            yield result.value;
        }
    } finally {
        await iterator.return?.();
    }
}

